import { test, expect } from '@playwright/test';

test.describe('Dashboard Sidebar Responsiveness', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display sidebar on desktop', async ({ page }) => {
    await page.setViewportSize({ width: 1280, height: 800 });
    const sidebar = page.getByRole('navigation', { name: 'Sidebar' });
    await expect(sidebar).toBeVisible();
  });

  test('should display bottom nav bar on mobile', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 });
    const bottomNavBar = page.getByRole('navigation', { name: 'Bottom Navigation' });
    await expect(bottomNavBar).toBeVisible();
    const sidebar = page.getByRole('navigation', { name: 'Sidebar' });
    await expect(sidebar).not.toBeVisible();
  });
});
